const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const suppliedSecret = headers['x-xvond-n8n-secret'] || headers['X-Xvond-N8N-Secret'];
const expectedSecret = $env.N8N_SHARED_SECRET;
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '');
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};
const configuredAction = data.action_config && typeof data.action_config === 'object' ? data.action_config : null;
const destination = configuredAction?.destination && typeof configuredAction.destination === 'object' ? configuredAction.destination : {};
const destinationType = String(destination.type || '').trim();
const fail = (error, code, extra = {}) => [{ json: { success: false, request_id: requestId, action, data: { code, ...extra }, error } }];
if (!expectedSecret || suppliedSecret !== expectedSecret) return fail('Unauthorized workflow request', 'unauthorized');
if (!requestId || !body.company_id || !body.agent_id || !action) return fail('Invalid workflow request contract', 'invalid_contract');
if (action === 'health_check') return [{ json: { success: true, request_id: requestId, action, data: { status: 'ok', engine: 'workflow', company_id: body.company_id, agent_id: body.agent_id }, error: null } }];
const routes = {
  'booking.check_availability': { adapter: 'booking', mutates: false, operation: 'check_availability' },
  'booking.execute': { adapter: 'booking', mutates: true, operation: 'execute' },
  'booking.cancel': { adapter: 'booking', mutates: true, operation: 'cancel' },
  'send_email.execute': { adapter: 'email', mutates: true, operation: 'execute' },
  'crm.upsert_contact': { adapter: 'crm', mutates: true },
  'crm.create_lead': { adapter: 'crm', mutates: true },
  'pos.create_order': { adapter: 'pos', mutates: true },
  'custom_api.execute': { adapter: 'custom_api', mutates: true, operation: 'execute' },
  'notification.send': { adapter: 'notification', mutates: true }
};
let route = routes[action];
let actionKey = '';
let operation = route?.operation || '';
if (!route) {
  const match = action.match(/^([a-z0-9][a-z0-9_\-]{0,127})\.(check_availability|execute|cancel)$/i);
  if (!match) return fail(`Unsupported workflow action: ${action}`, 'unsupported_action');
  actionKey = match[1];
  operation = match[2];
  const declaredActionType = String(data.action_type || '').trim();
  const moduleName = String(configuredAction?.module || '').trim();
  if (!configuredAction || !declaredActionType || declaredActionType !== actionKey || !moduleName) return fail('Invalid generic business action contract', 'invalid_business_action', { action_key: actionKey || null });
  route = { adapter: 'business', mutates: operation !== 'check_availability', action_key: actionKey, operation, module: moduleName, destination_type: destinationType || 'unconfigured' };
}
const idempotencyKey = String(data.idempotency_key || '');
if (route.mutates && !idempotencyKey) return fail('Mutating workflow action requires idempotency_key', 'missing_idempotency_key', { adapter: route.adapter });
if (configuredAction && destinationType === 'xvond_internal' && ['check_availability', 'execute', 'cancel'].includes(operation)) {
  return [{ json: { _dispatch: 'xvond_internal', company_id: body.company_id, agent_id: body.agent_id, conversation_id: body.conversation_id || null, action, request_id: requestId, data } }];
}
if (configuredAction && destinationType === 'integration' && ['check_availability', 'execute', 'cancel'].includes(operation)) {
  const integrationId = Number(destination.integration_id || 0);
  if (!integrationId) return fail('Connected integration is not selected', 'provider_not_configured', { destination_type: 'integration' });
  let registry = {};
  try { registry = JSON.parse($env.XVOND_WORKFLOW_INTEGRATIONS_JSON || '{}'); } catch (_e) { return fail('Workflow integration registry is invalid', 'provider_not_configured'); }
  const routeKey = `${body.company_id}:${integrationId}`;
  const target = registry[routeKey];
  if (!target || target.type !== 'webhook' || typeof target.url !== 'string' || !target.url.startsWith('https://')) return fail('Connected integration route is not configured', 'provider_not_configured', { integration_id: integrationId, route_key: routeKey });
  return [{ json: { _dispatch: 'connected_integration', company_id: body.company_id, agent_id: body.agent_id, conversation_id: body.conversation_id || null, integration_id: integrationId, route_key: routeKey, action, request_id: requestId, data } }];
}
return fail(`Workflow adapter is not configured: ${route.adapter}`, 'provider_not_configured', { adapter: route.adapter, action_key: route.action_key || null, operation: route.operation || null, module: route.module || null, destination_type: destinationType || route.destination_type || null, idempotency_key: idempotencyKey || null });
